//! Settings search (contract SETTINGS-WINDOW.md §4; the web's `settingsSearch.ts`): the searchable rows of the
//! Settings window (`settings_index.json`, a byte copy of the contract's `settings-index.json`) and the one matcher
//! both apps share. The unit test below replays the contract's vectors (`testvectors/settings-search/vectors.json`,
//! generated by the Python reference `contract/tools/settings-search-vectors.py`), so a change to the index or the
//! matcher on one side without the other fails here.
//!
//! - `normalize(s)` = NFD, drop combining marks, lowercase, every run of non-letters/digits → one space, trim.
//! - Query tokens = `normalize(q)` split on spaces (empty → no search). An entry's words = normalize(label + " " +
//!   section + " " + pane title + " " + keywords) split on spaces. It matches when EVERY token is a prefix of some word.
//! - Score 3 when normalize(label) starts with normalize(q); else 2 when every token is a prefix of a word of the
//!   label; else 1. Sorted by score (high first), then index order; at most 30.
//! - Operator-only entries (`"operator": true`) only for operators.
//!
//! QML reaches it through `SettingsController.searchSettings(query, operator)` (JSON) — see settings.rs.
use std::sync::OnceLock;

use serde::Deserialize;
use unicode_normalization::char::canonical_combining_class;
use unicode_normalization::UnicodeNormalization;

/// The index, embedded (byte copy of contract/settings-index.json).
pub const INDEX_JSON: &str = include_str!("settings_index.json");
/// At most this many results (§4).
pub const MAX_RESULTS: usize = 30;

#[derive(Debug, Clone, Deserialize)]
pub struct Pane {
    pub key: String,
    pub title: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Entry {
    pub id: String,
    pub pane: String,
    pub section: String,
    pub label: String,
    #[serde(default)]
    pub keywords: String,
    /// Invites: only for operators.
    #[serde(default)]
    pub operator: bool,
    /// Rows only the desktop has (shown here; the web hides them).
    #[serde(default, rename = "desktopOnly")]
    pub desktop_only: bool,
    /// Rows the web does not show (still shown here).
    #[serde(default, rename = "webHidden")]
    pub web_hidden: bool,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Index {
    pub v: u32,
    pub panes: Vec<Pane>,
    pub entries: Vec<Entry>,
}

impl Index {
    pub fn pane_title(&self, key: &str) -> &str {
        self.panes.iter().find(|p| p.key == key).map(|p| p.title.as_str()).unwrap_or("")
    }
}

/// The embedded index, parsed once.
pub fn index() -> &'static Index {
    static IDX: OnceLock<Index> = OnceLock::new();
    IDX.get_or_init(|| serde_json::from_str(INDEX_JSON).expect("settings_index.json is valid"))
}

/// Letters and digits in the Unicode sense (the reference's `\w` minus the underscore).
fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
}

/// One character's contribution to `normalize`: its NFD with the combining marks dropped, lowercased.
fn fold_char(c: char, out: &mut String) {
    for d in std::iter::once(c).nfd() {
        if canonical_combining_class(d) != 0 {
            continue;
        }
        for l in d.to_lowercase() {
            out.push(l);
        }
    }
}

/// §4 normalize: NFD, drop combining marks, lowercase, every run of non-letters/digits → one space, trim.
pub fn normalize(s: &str) -> String {
    let mut folded = String::with_capacity(s.len());
    for c in s.nfd() {
        if canonical_combining_class(c) != 0 {
            continue;
        }
        for l in c.to_lowercase() {
            folded.push(l);
        }
    }
    let mut out = String::with_capacity(folded.len());
    let mut gap = false;
    for c in folded.chars() {
        if is_word_char(c) {
            if gap && !out.is_empty() {
                out.push(' ');
            }
            gap = false;
            out.push(c);
        } else {
            gap = true;
        }
    }
    out
}

fn words(s: &str) -> Vec<&str> {
    s.split(' ').filter(|w| !w.is_empty()).collect()
}

fn every_token_prefixes(tokens: &[&str], ws: &[&str]) -> bool {
    tokens.iter().all(|t| ws.iter().any(|w| w.starts_with(t)))
}

/// A search result: the entry's position in the index and its score.
#[derive(Debug, Clone)]
pub struct Hit {
    pub index: usize,
    pub score: u8,
}

/// §4: the ordered results for `q` (operators see the operator-only entries).
pub fn search(q: &str, operator: bool) -> Vec<Hit> {
    search_in(index(), q, operator)
}

pub fn search_in(idx: &Index, q: &str, operator: bool) -> Vec<Hit> {
    let nq = normalize(q);
    if nq.is_empty() {
        return Vec::new();
    }
    let tokens = words(&nq);
    let mut hits: Vec<Hit> = Vec::new();
    for (i, e) in idx.entries.iter().enumerate() {
        if e.operator && !operator {
            continue;
        }
        let all = normalize(&format!("{} {} {} {}", e.label, e.section, idx.pane_title(&e.pane), e.keywords));
        if !every_token_prefixes(&tokens, &words(&all)) {
            continue;
        }
        let nl = normalize(&e.label);
        let score = if nl.starts_with(&nq) {
            3
        } else if every_token_prefixes(&tokens, &words(&nl)) {
            2
        } else {
            1
        };
        hits.push(Hit { index: i, score });
    }
    // stable: equal scores keep index order
    hits.sort_by(|a, b| b.score.cmp(&a.score));
    hits.truncate(MAX_RESULTS);
    hits
}

fn esc_into(c: char, out: &mut String) {
    match c {
        '&' => out.push_str("&amp;"),
        '<' => out.push_str("&lt;"),
        '>' => out.push_str("&gt;"),
        '"' => out.push_str("&quot;"),
        _ => out.push(c),
    }
}

/// The label as HTML with the matched part of each word bold: for every word of the label (a run of letters/digits),
/// the longest query token its normalized form starts with — those leading characters are wrapped in <b>. Everything
/// is HTML-escaped. (SETTINGS-WINDOW.md §4 "the matched part bold"; the web's settingsSearch.ts `markLabel`.)
pub fn mark_label(label: &str, q: &str) -> String {
    let nq = normalize(q);
    let tokens = words(&nq);
    let chars: Vec<char> = label.chars().collect();
    let mut out = String::with_capacity(label.len() + 16);
    let mut i = 0;
    while i < chars.len() {
        if !is_word_char(chars[i]) {
            esc_into(chars[i], &mut out);
            i += 1;
            continue;
        }
        let start = i;
        while i < chars.len() && is_word_char(chars[i]) {
            i += 1;
        }
        let word = &chars[start..i];
        // each original char → its folded length, so a token's length maps back onto the original characters
        let mut folded = String::new();
        let mut ends: Vec<usize> = Vec::with_capacity(word.len());
        for &c in word {
            fold_char(c, &mut folded);
            ends.push(folded.chars().count());
        }
        let best = tokens
            .iter()
            .filter(|t| folded.starts_with(**t))
            .map(|t| t.chars().count())
            .max()
            .unwrap_or(0);
        let bold = if best == 0 { 0 } else { ends.iter().position(|&e| e >= best).map(|p| p + 1).unwrap_or(word.len()) };
        if bold > 0 {
            out.push_str("<b>");
        }
        for (k, &c) in word.iter().enumerate() {
            esc_into(c, &mut out);
            if k + 1 == bold {
                out.push_str("</b>");
            }
        }
    }
    out
}

/// The results as the JSON the Settings window reads:
/// `[{id, pane, paneTitle, section, label, labelHtml, score}]`.
pub fn search_json(q: &str, operator: bool) -> String {
    let idx = index();
    let guest = crate::server_offer::guest_now();
    let arr: Vec<serde_json::Value> = search_in(idx, q, operator)
        .into_iter()
        // selfhost: the rows of a feature the server doesn't offer leave the search (server_offer.rs SETTING_GATES)
        .filter(|h| crate::server_offer::gate_of_setting(&idx.entries[h.index].id).is_none_or(crate::server_offer::feature_on_global))
        // … and the rows a temporary guest account never sees (GUEST_HIDDEN_SETTINGS: Change password)
        .filter(|h| crate::server_offer::setting_for_guest(&idx.entries[h.index].id, guest))
        .map(|h| {
            let e = &idx.entries[h.index];
            serde_json::json!({
                "id": e.id,
                "pane": e.pane,
                "paneTitle": idx.pane_title(&e.pane),
                "section": e.section,
                "label": e.label,
                "labelHtml": mark_label(&e.label, q),
                "score": h.score,
            })
        })
        .collect();
    serde_json::Value::Array(arr).to_string()
}

/// The pane of an entry id ("" when unknown) — the window's jump target.
pub fn pane_of(id: &str) -> &'static str {
    index().entries.iter().find(|e| e.id == id).map(|e| e.pane.as_str()).unwrap_or("")
}

#[cfg(test)]
mod tests {
    use super::*;

    const VECTORS: &str = include_str!("../testvectors/settings-search/vectors.json");

    #[derive(Deserialize)]
    struct Case {
        q: String,
        operator: bool,
        want: Vec<String>,
    }
    #[derive(Deserialize)]
    struct Vectors {
        format: String,
        v: u32,
        cases: Vec<Case>,
    }

    #[test]
    fn replays_the_contract_vectors() {
        let vs: Vectors = serde_json::from_str(VECTORS).unwrap();
        assert_eq!(vs.format, "tinhat-settings-search-vectors");
        assert_eq!(vs.v, 1);
        assert!(vs.cases.len() >= 40, "the contract ships 40 cases");
        let idx = index();
        for c in &vs.cases {
            let got: Vec<String> = search_in(idx, &c.q, c.operator).iter().map(|h| idx.entries[h.index].id.clone()).collect();
            assert_eq!(got, c.want, "query {:?} operator={}", c.q, c.operator);
        }
    }

    #[test]
    fn index_is_the_contract_v1_and_every_entry_has_a_pane() {
        let idx = index();
        assert_eq!(idx.v, 1);
        let keys: Vec<&str> = idx.panes.iter().map(|p| p.key.as_str()).collect();
        assert_eq!(
            keys,
            ["profile", "privacy", "security", "invites", "guests", "audio", "calls", "appearance", "notifications", "shortcuts", "overlay", "about"]
        );
        let mut seen = std::collections::HashSet::new();
        for e in &idx.entries {
            assert!(keys.contains(&e.pane.as_str()), "{} has an unknown pane {}", e.id, e.pane);
            assert!(e.id.starts_with(&format!("{}.", e.pane)), "{} is not under its pane", e.id);
            assert!(seen.insert(e.id.clone()), "duplicate id {}", e.id);
        }
        assert_eq!(pane_of("audio.echo-cancellation"), "audio");
        assert_eq!(pane_of("nope"), "");
    }

    #[test]
    fn normalize_follows_the_reference() {
        assert_eq!(normalize("  Écho "), "echo");
        assert_eq!(normalize("Who's talking?"), "who s talking");
        assert_eq!(normalize("SCREEN   share"), "screen share");
        assert_eq!(normalize("12/24-hour"), "12 24 hour");
        assert_eq!(normalize("snake_case"), "snake case");
        assert_eq!(normalize("   "), "");
        assert_eq!(normalize("Ünïcödé"), "unicode");
    }

    #[test]
    fn operators_alone_find_invites() {
        let ids = |op: bool| -> Vec<String> { search("invite", op).iter().map(|h| index().entries[h.index].id.clone()).collect() };
        assert!(ids(true).iter().any(|i| i.starts_with("invites.")));
        assert!(!ids(false).iter().any(|i| i.starts_with("invites.")));
    }

    #[test]
    fn marks_the_matched_part_of_each_word() {
        assert_eq!(mark_label("Input device", "in"), "<b>In</b>put device");
        assert_eq!(mark_label("Sign out", "sign out"), "<b>Sign</b> <b>out</b>");
        assert_eq!(mark_label("Écho cancel", "ech"), "<b>Éch</b>o cancel");
        assert_eq!(mark_label("Camera quality", "camera qual"), "<b>Camera</b> <b>qual</b>ity");
        assert_eq!(mark_label("Who's talking", "talk"), "Who's <b>talk</b>ing");
        assert_eq!(mark_label("Mentions and DMs", "mic"), "Mentions and DMs");
        assert_eq!(mark_label("A <b> & c", "b"), "A &lt;<b>b</b>&gt; &amp; c");
    }

    #[test]
    fn json_carries_what_the_window_reads() {
        let v: serde_json::Value = serde_json::from_str(&search_json("mic", false)).unwrap();
        let a = v.as_array().unwrap();
        assert_eq!(a.len(), 7);
        assert_eq!(a[0]["id"], "audio.input-device");
        assert_eq!(a[0]["paneTitle"], "Audio");
        assert_eq!(a[0]["section"], "Microphone");
        assert_eq!(a[0]["labelHtml"], "Input device");
        assert_eq!(search_json("", true), "[]");
    }
}
